import React from 'react';
import { useNavigate } from 'react-router-dom';

const Home = () => {
  const navigate = useNavigate();

  const goToLogin = () => {
    navigate('/login'); // Navigate to the login page
  };

  return (
    <div>
      <h2>Find Similar Tracks</h2>
      <button onClick={goToLogin}>Login with Spotify</button>
      {/* Rest of your Home component, like the TrackSearch component */}
    </div>
  );
};

export default Home;
